-- Dumping structure for table cit_lms.lessons
CREATE TABLE IF NOT EXISTS `lessons` (
  `lessons_id` int NOT NULL AUTO_INCREMENT,
  `subject_id` int NOT NULL,
  `user_teacher_id` int NOT NULL,
  `lesson_title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `lesson_description` text COLLATE utf8mb4_unicode_ci,
  `learning_objectives` text COLLATE utf8mb4_unicode_ci COMMENT 'JSON array of objectives',
  `prerequisite_lessons_id` int DEFAULT NULL,
  `lesson_content` longtext COLLATE utf8mb4_unicode_ci,
  `lesson_order` int DEFAULT '1',
  `estimated_time` int DEFAULT '30',
  `difficulty` enum('beginner','intermediate','advanced') COLLATE utf8mb4_unicode_ci DEFAULT 'beginner',
  `status` enum('draft','published','archived') COLLATE utf8mb4_unicode_ci DEFAULT 'draft',
  `due_date` datetime DEFAULT NULL,
  `grading_period` varchar(2) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'P1' COMMENT 'P1=Midterms P2=Prefinals P3=Finals',
  `published_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `total_points` decimal(8,2) DEFAULT NULL,
  PRIMARY KEY (`lessons_id`),
  KEY `idx_lessons_subject` (`subject_id`),
  KEY `idx_lessons_teacher` (`user_teacher_id`),
  KEY `idx_lessons_status` (`status`),
  KEY `idx_lessons_subject_status` (`subject_id`,`status`),
  CONSTRAINT `lessons_ibfk_1` FOREIGN KEY (`subject_id`) REFERENCES `subject` (`subject_id`) ON DELETE CASCADE,
  CONSTRAINT `lessons_ibfk_2` FOREIGN KEY (`user_teacher_id`) REFERENCES `users` (`users_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

