-- Dumping structure for table cit_lms.section
CREATE TABLE IF NOT EXISTS `section` (
  `section_id` int NOT NULL AUTO_INCREMENT,
  `section_name` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `program_id` int DEFAULT NULL,
  `year_level` tinyint(1) DEFAULT NULL,
  `semester_id` int DEFAULT NULL,
  `enrollment_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `max_students` int DEFAULT '40',
  `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci DEFAULT 'active',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`section_id`),
  UNIQUE KEY `enrollment_code` (`enrollment_code`),
  KEY `idx_section_program` (`program_id`),
  KEY `idx_section_semester` (`semester_id`),
  KEY `idx_section_name` (`section_name`)
) ENGINE=InnoDB AUTO_INCREMENT=1649 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

