CREATE TABLE IF NOT EXISTS `section_subject` (
  `section_subject_id` int NOT NULL AUTO_INCREMENT,
  `section_id` int NOT NULL,
  `subject_offered_id` int NOT NULL,
  `enrollment_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `schedule` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `room` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci DEFAULT 'active',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`section_subject_id`),
  UNIQUE KEY `uq_sec_subj` (`section_id`,`subject_offered_id`),
  UNIQUE KEY `uq_section_subject_code` (`enrollment_code`),
  KEY `fk_secsubj_section` (`section_id`),
  KEY `fk_secsubj_offered` (`subject_offered_id`)
) ENGINE=InnoDB AUTO_INCREMENT=603 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

