  `subject_id` int NOT NULL,
  `lessons_id` int DEFAULT NULL,
  `quiz_id` int DEFAULT NULL,
  `file_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `original_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `file_path` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `file_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'document',
  `file_size` int DEFAULT '0',
  `is_submitted` tinyint(1) NOT NULL DEFAULT '0',
  `submitted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `points_earned` decimal(8,2) DEFAULT NULL,
  PRIMARY KEY (`file_id`),
  KEY `idx_student_lesson` (`user_student_id`,`lessons_id`),
  KEY `idx_student_quiz` (`user_student_id`,`quiz_id`),
  KEY `idx_subject` (`subject_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

