-- Dumping structure for table cit_lms.subject_module_documents
CREATE TABLE IF NOT EXISTS `subject_module_documents` (
  `doc_id` int NOT NULL AUTO_INCREMENT,
  `subject_id` int NOT NULL,
  `module_number` tinyint NOT NULL,
  `doc_type` enum('teaching_guide','sas') COLLATE utf8mb4_unicode_ci NOT NULL,
  `file_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `original_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `file_path` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `file_size` int NOT NULL DEFAULT '0',
  `uploaded_by` int DEFAULT NULL,
  `is_published` tinyint(1) NOT NULL DEFAULT '0',
  `publish_at` datetime DEFAULT NULL,
  `uploaded_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`doc_id`),
  UNIQUE KEY `uq_smd` (`subject_id`,`module_number`,`doc_type`),
  KEY `idx_smd_subject` (`subject_id`)
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

