-- Dumping structure for table cit_lms.subject_offered
CREATE TABLE IF NOT EXISTS `subject_offered` (
  `subject_offered_id` int NOT NULL AUTO_INCREMENT,
  `subject_id` int NOT NULL,
  `semester_id` int DEFAULT NULL,
  `batch` enum('1st Year','2nd Year','3rd Year','4th Year') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_teacher_id` int DEFAULT NULL,
  `max_students` int DEFAULT '40',
  `status` enum('open','closed','cancelled') COLLATE utf8mb4_unicode_ci DEFAULT 'open',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `current_period` varchar(2) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'P1' COMMENT 'Current released grading period: P1=Midterms P2=Prefinals P3=Finals',
  `grading_type` enum('raw_score','global') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'raw_score',
  PRIMARY KEY (`subject_offered_id`),
  KEY `fk_subject_offered_teacher` (`user_teacher_id`),
  KEY `idx_subject_id` (`subject_id`),
  KEY `idx_so_status` (`status`),
  KEY `idx_so_teacher_status` (`user_teacher_id`,`status`),
  KEY `idx_subject_offered_semester_id` (`semester_id`),
  CONSTRAINT `fk_so_subject` FOREIGN KEY (`subject_id`) REFERENCES `subject` (`subject_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1309 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

