  KEY `idx_users_student_id` (`student_id`),
  KEY `idx_users_employee_id` (`employee_id`),
  KEY `idx_users_campus` (`campus_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2937 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

